import React, { createContext, useContext, useState, useEffect } from 'react';
import themes from './themes.json'
const ThemeContext = createContext();


const useDynamicStyles = (stylesObject) => {
    useEffect(() => {
      const styleSheet = document.createElement('style');
      styleSheet.type = 'text/css';
  
      let styles = '';
      for (const selector in stylesObject) {
        styles += `${selector} {`;
        for (const property in stylesObject[selector]) {
          const value = stylesObject[selector][property];
          styles += `${property}: ${value};`;
        }
        styles += '} ';
      }
  
      styleSheet.innerText = styles;
      document.head.appendChild(styleSheet);
  
      return () => {
        document.head.removeChild(styleSheet);
      };
    }, [stylesObject]);
  };


export const ThemeProvider = ({ children }) => {
    const [theme, setTheme] = useState(
        // Object.keys(themes)[Math.floor(Math.random() * Object.keys().length)]
        Object.keys(themes)[Math.floor(Object.keys(themes).length * Math.random())]
    )
    const currentTheme = themes[theme]
    // console.log(currentTheme)
    useEffect(() => {
        document.body.style.backgroundColor = currentTheme.background;
        return () => {
            document.body.style = {backgroundColor: currentTheme.background};
        }
    }, [currentTheme])
    useDynamicStyles({
        // src/index.js applet containers
        ".applet": {
            padding: '1em',
            height: '100%',
            width: '100%',
            outline: `solid 1px ${currentTheme.color1}`,
            // "outline": `solid 1px green`
        },
        // OS Credit
        "#creds a": {
            color: currentTheme.foreground
        },
        // JSON Schema Viewer
        ".node circle,.node rect": {
            fill: currentTheme.color14,
            stroke: currentTheme.color14,
        },
        ".node text": {
            fill: currentTheme.color13
        },
        "path.link": {
            stroke: currentTheme.color12
        },
        "::selection": {
            backgroundColor: currentTheme.cursor
        }
    })
    return (
        <ThemeContext.Provider value={{ theme, setTheme }}>
            <div
                style={{
                    backgroundColor: currentTheme.background,
                    color: currentTheme.foreground
                }}
            >
                {children}
            </div>
        </ThemeContext.Provider>
    )
}


export const useTheme = () => useContext(ThemeContext);


export const ChangeTheme = () => {
    const { theme, setTheme } = useTheme();

    const updateTheme = (event) => {
        setTheme(event.target.value)
    }

    return (
        <div style={{display: "flex", justifyContent: "center"}}>
            <select
                id="theme"
                name="theme"
                value={theme}
                onChange={updateTheme}
            >
                {Object.keys(themes).map((x) => (<option key={x} value={x}>{x}</option>))}
            </select>
        </div>
    );
};

